package com.easybikerentals.controller;
import com.easybikerentals.entity.ContactMessage; import com.easybikerentals.repository.ContactRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/contact") public class ContactController {private final ContactRepository repo; public ContactController(ContactRepository r){repo=r;} record Message(@NotBlank String name,@Email @NotBlank String email,String phone,@NotBlank String subject,@NotBlank @Size(max=4000) String message){} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ContactMessage send(@Valid @RequestBody Message m){var c=new ContactMessage();c.name=m.name();c.email=m.email();c.phone=m.phone();c.subject=m.subject();c.message=m.message();return repo.save(c);}}
